"use client"

import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { Controller, FieldValues, Path, useFormContext } from "react-hook-form"

type TextFieldProps<TValues extends FieldValues> = {
  name: Path<TValues>
  label?: string
  type?: "text" | "email" | "number" | "password" | "tel" | "url"
  placeholder?: string
  description?: string
  required?: boolean
  disabled?: boolean
  className?: string
  inputClass?: string
  min?: number | string
  max?: number | string
  step?: number | string
  autoComplete?: string
  onValueChange?: (value: string | number | null) => void
}

/**
 * A single-line text input bound to a react-hook-form field via `Controller`.
 *
 * Renders a labeled `Field` with an `Input`, marks the field invalid when the
 * schema fails, and shows the resolved error message via `FieldError`. Works
 * inside a `GenericForm` (or any `FormProvider`).
 *
 * When `type === "number"`, the value is coerced to a number (or `null` when
 * empty) before being written to the form, matching common zod+api payloads.
 * Pass `onValueChange` for custom value coercion/transforms.
 */
const TextField = <TValues extends FieldValues>({
  name,
  label,
  type = "text",
  placeholder,
  required = false,
  disabled = false,
  className,
  inputClass,
  min,
  max,
  step,
  autoComplete,
  onValueChange,
}: TextFieldProps<TValues>) => {
  const { control } = useFormContext<TValues>()

  return (
    <Controller
      name={name}
      control={control}
      render={({ field, fieldState }) => (
        <Field data-invalid={fieldState.invalid} className={className}>
          {label && (
            <FieldLabel htmlFor={name}>
              <span>{label}</span>
              {required && <span className="text-destructive">*</span>}
            </FieldLabel>
          )}
          <Input
            ref={field.ref}
            id={name}
            name={field.name}
            type={type}
            value={field.value ?? ""}
            onChange={(e) => {
              if (onValueChange) {
                onValueChange(
                  type === "number"
                    ? e.target.value === ""
                      ? null
                      : Number(e.target.value)
                    : e.target.value,
                )
                return
              }
              if (type === "number") {
                const value =
                  e.target.value === "" ? null : Number(e.target.value)
                field.onChange(value)
                return
              }
              field.onChange(e.target.value)
            }}
            placeholder={placeholder}
            disabled={disabled}
            min={min}
            max={max}
            step={step}
            autoComplete={autoComplete}
            className={cn(inputClass)}
          />
          {fieldState.invalid && <FieldError errors={[fieldState.error]} />}
        </Field>
      )}
    />
  )
}

TextField.displayName = "TextField"

export { TextField, type TextFieldProps }

"use client"

import { useDebouncedCallback } from "@/components/edust-kit/hooks/use-debounced-callback"
import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import { Input } from "@/components/ui/input"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"

import * as React from "react"

export interface SelectFieldItem {
  id: string
  name?: string
  label?: string
}

export interface BaseSelectParams {
  search_by_name?: string
  page?: number
  limit?: number
  [key: string]: unknown
}

export interface AsyncSelectFieldProps<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
> {
  value?: string
  onChange: (id: string) => void
  placeholder?: string
  debounceDelay?: number
  searchPlaceholder?: string
  searchParamKey?: keyof TParams
  useDataHook: (params: TParams) => {
    data?: { data?: { items?: T[] } }
    isFetching: boolean
    error: unknown
  }
  selectedItemData?: { data?: { items?: T[] } }
  getItemDisplayValue: (item: T) => string
  getItemKey?: (item: T) => string
  getItemValue?: (item: T) => string
  renderItemLabel?: (item: T) => React.ReactNode
  additionalParams?: Partial<Omit<TParams, keyof BaseSelectParams>>
  disabled?: boolean
  className?: string
  showSearchIcon?: boolean
  /**
   * When `true`, the dropdown list is fetched only after the popover is opened
   * instead of on mount. Use this on forms with many async selects to avoid
   * firing a burst of requests at page load.
   */
  lazy?: boolean
}

const defaultGetItemValue = (item: SelectFieldItem) => item.id

interface AsyncSelectCommandProps<T extends SelectFieldItem> {
  search: string
  setSearch: (value: string) => void
  debouncedSetSearch: (value: string) => void
  searchPlaceholder: string
  showSearchIcon: boolean
  items: T[]
  isFetching: boolean
  error: unknown
  getItemKey?: (item: T) => string
  getItemValue: (item: T) => string
  getItemDisplayValue: (item: T) => string
  renderItemLabel?: (item: T) => React.ReactNode
  onSelect: (itemValue: string) => void
}

function AsyncSelectCommand<T extends SelectFieldItem>({
  search,
  setSearch,
  debouncedSetSearch,
  searchPlaceholder,
  showSearchIcon,
  items,
  isFetching,
  error,
  getItemKey,
  getItemValue,
  getItemDisplayValue,
  renderItemLabel,
  onSelect,
}: AsyncSelectCommandProps<T>) {
  return (
    <Command shouldFilter={false}>
      {showSearchIcon ? (
        <CommandInput
          placeholder={searchPlaceholder}
          value={search}
          onValueChange={(value) => {
            setSearch(value)
            debouncedSetSearch(value)
          }}
        />
      ) : (
        <div className="px-1 pt-1">
          <Input
            data-slot="command-input"
            placeholder={searchPlaceholder}
            value={search}
            onChange={(e) => {
              setSearch(e.target.value)
              debouncedSetSearch(e.target.value)
            }}
            className="h-8 w-full border-0 bg-transparent text-sm shadow-none focus-visible:ring-0"
          />
        </div>
      )}
      <CommandList>
        {isFetching ? (
          <div className="text-muted-foreground flex items-center justify-center py-6 text-sm">
            Loading...
          </div>
        ) : error ? (
          <CommandEmpty>Failed to load items.</CommandEmpty>
        ) : items.length === 0 ? (
          <CommandEmpty>
            {search ? "No items found." : "No items available."}
          </CommandEmpty>
        ) : (
          <CommandGroup className="max-h-75 overflow-y-auto">
            {items.map((item) => {
              const itemValue = getItemValue(item)
              return (
                <CommandItem
                  key={getItemKey ? getItemKey(item) : itemValue}
                  value={itemValue}
                  onSelect={() => onSelect(itemValue)}
                >
                  {renderItemLabel
                    ? renderItemLabel(item)
                    : getItemDisplayValue(item)}
                </CommandItem>
              )
            })}
          </CommandGroup>
        )}
      </CommandList>
    </Command>
  )
}

interface UseAsyncSelectFieldStateConfig<TParams extends BaseSelectParams> {
  onChange: (id: string) => void
  debounceDelay: number
  searchParamKey: keyof TParams
  additionalParams: Partial<Omit<TParams, keyof BaseSelectParams>>
}

function useAsyncSelectFieldState<TParams extends BaseSelectParams>({
  onChange,
  debounceDelay,
  searchParamKey,
  additionalParams,
}: UseAsyncSelectFieldStateConfig<TParams>) {
  const [open, setOpen] = React.useState(false)
  const [search, setSearch] = React.useState("")
  const [debouncedSearch, setDebouncedSearch] = React.useState("")
  const triggerRef = React.useRef<HTMLButtonElement>(null)
  const [contentWidth, setContentWidth] = React.useState<number | undefined>()
  const debouncedSetSearch = useDebouncedCallback(
    setDebouncedSearch,
    debounceDelay,
  )

  React.useEffect(() => {
    if (!open || !triggerRef.current) return
    const el = triggerRef.current.closest(
      "[data-slot='field-control'], [data-slot='form-item'], form, [role='group']",
    ) as HTMLElement | null
    const w = el?.offsetWidth ?? triggerRef.current.parentElement?.offsetWidth
    setContentWidth(w)
  }, [open])

  const onOpenChange = React.useCallback((nextOpen: boolean) => {
    setOpen(nextOpen)
    if (!nextOpen) {
      setSearch("")
      setDebouncedSearch("")
    }
  }, [])

  const params = React.useMemo(() => {
    return {
      [searchParamKey]: debouncedSearch || undefined,
      ...additionalParams,
    } as TParams
  }, [debouncedSearch, additionalParams, searchParamKey])

  const handleSelect = React.useCallback(
    (itemValue: string) => {
      onChange(itemValue)
      setOpen(false)
    },
    [onChange],
  )

  return {
    open,
    search,
    setSearch,
    debouncedSetSearch,
    triggerRef,
    contentWidth,
    onOpenChange,
    params,
    handleSelect,
  }
}

interface AsyncSelectShellProps<T extends SelectFieldItem> {
  open: boolean
  onOpenChange: (open: boolean) => void
  triggerRef: React.RefObject<HTMLButtonElement | null>
  disabled: boolean
  className?: string
  selectedItem?: T
  getItemDisplayValue: (item: T) => string
  placeholder: string
  contentWidth: number | undefined
  children: React.ReactNode
}

function AsyncSelectShell<T extends SelectFieldItem>({
  open,
  onOpenChange,
  triggerRef,
  disabled,
  className,
  selectedItem,
  getItemDisplayValue,
  placeholder,
  contentWidth,
  children,
}: AsyncSelectShellProps<T>) {
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild disabled={disabled}>
        <Button
          ref={triggerRef}
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn(
            "w-full justify-between font-normal",
            !selectedItem && "text-muted-foreground",
            className,
          )}
        >
          <span className="truncate">
            {selectedItem ? getItemDisplayValue(selectedItem) : placeholder}
          </span>
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="p-0"
        style={{
          minWidth: contentWidth,
          maxWidth: "100vw",
        }}
        align="start"
      >
        {children}
      </PopoverContent>
    </Popover>
  )
}

interface AsyncSelectLazyBodyProps<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
> extends Omit<AsyncSelectCommandProps<T>, "items" | "isFetching" | "error"> {
  params: TParams
  useDataHook: AsyncSelectFieldProps<T, TParams>["useDataHook"]
}

function AsyncSelectLazyBody<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
>({
  params,
  useDataHook,
  ...commandProps
}: AsyncSelectLazyBodyProps<T, TParams>) {
  const { data, isFetching, error } = useDataHook(params)
  const items = React.useMemo(() => data?.data?.items ?? [], [data])

  return (
    <AsyncSelectCommand
      {...commandProps}
      items={items}
      isFetching={isFetching}
      error={error}
    />
  )
}

export function AsyncSelectField<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
>({
  value,
  onChange,
  placeholder = "Select...",
  debounceDelay = 500,
  searchPlaceholder = "Search...",
  searchParamKey = "search_by_name" as keyof TParams,
  useDataHook,
  selectedItemData,
  getItemDisplayValue,
  getItemKey,
  getItemValue,
  renderItemLabel,
  additionalParams = {},
  disabled = false,
  className,
  showSearchIcon = false,
  lazy = false,
}: AsyncSelectFieldProps<T, TParams>) {
  const state = useAsyncSelectFieldState<TParams>({
    onChange,
    debounceDelay,
    searchParamKey,
    additionalParams,
  })

  const getValue = React.useMemo(
    () => getItemValue ?? defaultGetItemValue,
    [getItemValue],
  )

  const selectedItemDataItems = React.useMemo(
    () => selectedItemData?.data?.items ?? [],
    [selectedItemData],
  )

  const selectedItemFromData = React.useMemo(
    () => selectedItemDataItems.find((item) => getValue(item) === value),
    [selectedItemDataItems, value, getValue],
  )

  const commandProps = {
    search: state.search,
    setSearch: state.setSearch,
    debouncedSetSearch: state.debouncedSetSearch,
    searchPlaceholder,
    showSearchIcon,
    getItemKey,
    getItemValue: getValue,
    getItemDisplayValue,
    renderItemLabel,
    onSelect: state.handleSelect,
  }

  if (lazy) {
    return (
      <AsyncSelectShell
        open={state.open}
        onOpenChange={state.onOpenChange}
        triggerRef={state.triggerRef}
        disabled={disabled}
        className={className}
        selectedItem={selectedItemFromData}
        getItemDisplayValue={getItemDisplayValue}
        placeholder={placeholder}
        contentWidth={state.contentWidth}
      >
        {state.open ? (
          <AsyncSelectLazyBody
            params={state.params}
            useDataHook={useDataHook}
            {...commandProps}
          />
        ) : null}
      </AsyncSelectShell>
    )
  }

  return (
    <AsyncSelectEager
      value={value}
      useDataHook={useDataHook}
      selectedItemFromData={selectedItemFromData}
      getItemDisplayValue={getItemDisplayValue}
      disabled={disabled}
      className={className}
      placeholder={placeholder}
      state={state}
      getValue={getValue}
      commandProps={commandProps}
    />
  )
}

interface AsyncSelectEagerProps<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
> {
  value?: string
  useDataHook: AsyncSelectFieldProps<T, TParams>["useDataHook"]
  selectedItemFromData?: T
  getItemDisplayValue: (item: T) => string
  disabled: boolean
  className?: string
  placeholder: string
  state: ReturnType<typeof useAsyncSelectFieldState<TParams>>
  getValue: (item: T) => string
  commandProps: Omit<
    AsyncSelectCommandProps<T>,
    "items" | "isFetching" | "error"
  >
}

function AsyncSelectEager<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
>({
  value,
  useDataHook,
  selectedItemFromData,
  getItemDisplayValue,
  disabled,
  className,
  placeholder,
  state,
  getValue,
  commandProps,
}: AsyncSelectEagerProps<T, TParams>) {
  const { data, isFetching, error } = useDataHook(state.params)

  const items = React.useMemo(() => data?.data?.items ?? [], [data])

  const selectedItemFromList = React.useMemo(
    () => items.find((item) => getValue(item) === value),
    [items, value, getValue],
  )

  const selectedItem = selectedItemFromList ?? selectedItemFromData

  return (
    <AsyncSelectShell
      open={state.open}
      onOpenChange={state.onOpenChange}
      triggerRef={state.triggerRef}
      disabled={disabled}
      className={className}
      selectedItem={selectedItem}
      getItemDisplayValue={getItemDisplayValue}
      placeholder={placeholder}
      contentWidth={state.contentWidth}
    >
      <AsyncSelectCommand
        {...commandProps}
        items={items}
        isFetching={isFetching}
        error={error}
      />
    </AsyncSelectShell>
  )
}

"use client"

import { useDebouncedCallback } from "@/components/edust-kit/hooks/use-debounced-callback"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import { Input } from "@/components/ui/input"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { cn } from "@/lib/utils"
import { ChevronsUpDownIcon, XIcon } from "lucide-react"

import * as React from "react"

import type { BaseSelectParams, SelectFieldItem } from "./async-select-field"

export type { BaseSelectParams, SelectFieldItem }

export interface AsyncMultiSelectFieldProps<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
> {
  value?: string[]
  onChange: (values: string[]) => void
  placeholder?: string
  debounceDelay?: number
  searchPlaceholder?: string
  searchParamKey?: keyof TParams
  useDataHook: (params: TParams) => {
    data?: { data?: { items?: T[] } }
    isFetching: boolean
    error: unknown
  }
  selectedItemsData?: { data?: { items?: T[] } }
  getItemDisplayValue: (item: T) => string
  getItemKey?: (item: T) => string
  getItemValue?: (item: T) => string
  renderItemLabel?: (item: T) => React.ReactNode
  additionalParams?: Partial<Omit<TParams, keyof BaseSelectParams>>
  disabled?: boolean
  className?: string
  badgeClassName?: string
  maxSelected?: number
  maxBadges?: number
  showSearchIcon?: boolean
  lazy?: boolean
  emptyIndicator?: React.ReactNode
}

const defaultGetItemValue = (item: SelectFieldItem) => item.id

interface AsyncMultiSelectCommandProps<T extends SelectFieldItem> {
  search: string
  setSearch: (value: string) => void
  debouncedSetSearch: (value: string) => void
  searchPlaceholder: string
  showSearchIcon: boolean
  items: T[]
  value: string[]
  isFetching: boolean
  error: unknown
  maxSelected?: number
  emptyIndicator?: React.ReactNode
  getItemKey?: (item: T) => string
  getItemValue: (item: T) => string
  getItemDisplayValue: (item: T) => string
  renderItemLabel?: (item: T) => React.ReactNode
  onToggle: (itemValue: string) => void
}

function AsyncMultiSelectCommand<T extends SelectFieldItem>({
  search,
  setSearch,
  debouncedSetSearch,
  searchPlaceholder,
  showSearchIcon,
  items,
  value,
  isFetching,
  error,
  maxSelected,
  emptyIndicator,
  getItemKey,
  getItemValue,
  getItemDisplayValue,
  renderItemLabel,
  onToggle,
}: AsyncMultiSelectCommandProps<T>) {
  const isMaxReached = maxSelected ? value.length >= maxSelected : false

  return (
    <Command shouldFilter={false}>
      {showSearchIcon ? (
        <CommandInput
          placeholder={searchPlaceholder}
          value={search}
          onValueChange={(value) => {
            setSearch(value)
            debouncedSetSearch(value)
          }}
        />
      ) : (
        <div className="px-1 pt-1">
          <Input
            data-slot="command-input"
            placeholder={searchPlaceholder}
            value={search}
            onChange={(e) => {
              setSearch(e.target.value)
              debouncedSetSearch(e.target.value)
            }}
            className="h-8 w-full border-0 bg-transparent text-sm shadow-none focus-visible:ring-0"
          />
        </div>
      )}
      <CommandList>
        {isFetching ? (
          <div className="text-muted-foreground flex items-center justify-center py-6 text-sm">
            Loading...
          </div>
        ) : error ? (
          <CommandEmpty>Failed to load items.</CommandEmpty>
        ) : items.length === 0 ? (
          <CommandEmpty>
            {isMaxReached
              ? `Maximum ${maxSelected} items selected`
              : (emptyIndicator ??
                (search ? "No items found." : "No items available."))}
          </CommandEmpty>
        ) : (
          <CommandGroup className="max-h-75 overflow-y-auto">
            {isMaxReached && (
              <p className="text-muted-foreground px-2 py-1.5 text-sm">
                Maximum {maxSelected} items selected
              </p>
            )}
            {items.map((item) => {
              const itemValue = getItemValue(item)
              const isSelected = value.includes(itemValue)
              return (
                <CommandItem
                  key={getItemKey ? getItemKey(item) : itemValue}
                  value={itemValue}
                  data-checked={isSelected}
                  aria-selected={isSelected}
                  onSelect={() => onToggle(itemValue)}
                  className="cursor-pointer"
                >
                  {renderItemLabel
                    ? renderItemLabel(item)
                    : getItemDisplayValue(item)}
                </CommandItem>
              )
            })}
          </CommandGroup>
        )}
      </CommandList>
    </Command>
  )
}

function buildSelectedItems<T extends SelectFieldItem>(
  items: T[],
  extraItems: T[],
  value: string[],
  getItemValue: (item: T) => string,
): T[] {
  const byValue = new Map<string, T>()
  for (const item of [...items, ...extraItems]) {
    const itemValue = getItemValue(item)
    if (!byValue.has(itemValue)) byValue.set(itemValue, item)
  }
  return value
    .map((itemValue) => byValue.get(itemValue))
    .filter((item): item is T => Boolean(item))
}

interface UseAsyncMultiSelectFieldStateConfig<
  TParams extends BaseSelectParams,
> {
  debounceDelay: number
  searchParamKey: keyof TParams
  additionalParams: Partial<Omit<TParams, keyof BaseSelectParams>>
}

function useAsyncMultiSelectFieldState<TParams extends BaseSelectParams>({
  debounceDelay,
  searchParamKey,
  additionalParams,
}: UseAsyncMultiSelectFieldStateConfig<TParams>) {
  const [open, setOpen] = React.useState(false)
  const [search, setSearch] = React.useState("")
  const [debouncedSearch, setDebouncedSearch] = React.useState("")
  const triggerRef = React.useRef<HTMLButtonElement>(null)
  const [contentWidth, setContentWidth] = React.useState<number | undefined>()
  const debouncedSetSearch = useDebouncedCallback(
    setDebouncedSearch,
    debounceDelay,
  )

  React.useEffect(() => {
    if (!open || !triggerRef.current) return
    const el = triggerRef.current.closest(
      "[data-slot='field-control'], [data-slot='form-item'], form, [role='group']",
    ) as HTMLElement | null
    const w = el?.offsetWidth ?? triggerRef.current.parentElement?.offsetWidth
    setContentWidth(w)
  }, [open])

  const onOpenChange = React.useCallback((nextOpen: boolean) => {
    setOpen(nextOpen)
    if (!nextOpen) {
      setSearch("")
      setDebouncedSearch("")
    }
  }, [])

  const params = React.useMemo(() => {
    return {
      [searchParamKey]: debouncedSearch || undefined,
      ...additionalParams,
    } as TParams
  }, [debouncedSearch, additionalParams, searchParamKey])

  return {
    open,
    search,
    setSearch,
    debouncedSetSearch,
    triggerRef,
    contentWidth,
    onOpenChange,
    params,
  }
}

interface AsyncMultiSelectShellProps<T extends SelectFieldItem> {
  open: boolean
  onOpenChange: (open: boolean) => void
  triggerRef: React.RefObject<HTMLButtonElement | null>
  disabled: boolean
  className?: string
  value: string[]
  selectedItems: T[]
  getItemValue: (item: T) => string
  getItemDisplayValue: (item: T) => string
  placeholder: string
  badgeClassName?: string
  maxBadges: number
  contentWidth: number | undefined
  onUnselect: (item: T) => void
  onClear: () => void
  children: React.ReactNode
}

function AsyncMultiSelectShell<T extends SelectFieldItem>({
  open,
  onOpenChange,
  triggerRef,
  disabled,
  className,
  value,
  selectedItems,
  getItemValue,
  getItemDisplayValue,
  placeholder,
  badgeClassName,
  maxBadges,
  contentWidth,
  onUnselect,
  onClear,
  children,
}: AsyncMultiSelectShellProps<T>) {
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild disabled={disabled}>
        <Button
          ref={triggerRef}
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn(
            "h-auto min-h-8 w-full justify-between gap-0 px-2 py-1.5 font-normal",
            selectedItems.length === 0 && "text-muted-foreground",
            className,
          )}
        >
          <span className="flex min-w-0 flex-wrap items-center gap-1">
            {selectedItems.length > 0 ? (
              <>
                {selectedItems.slice(0, maxBadges).map((item) => (
                  <Badge
                    key={getItemValue(item)}
                    variant="secondary"
                    className={cn(
                      "gap-1 pr-1 whitespace-nowrap",
                      badgeClassName,
                    )}
                  >
                    {getItemDisplayValue(item)}
                    <span
                      role="button"
                      tabIndex={0}
                      aria-label={`Remove ${getItemDisplayValue(item)}`}
                      className="text-muted-foreground hover:bg-muted-foreground/20 hover:text-foreground focus-visible:ring-ring rounded-full outline-none focus-visible:ring-2"
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault()
                          e.stopPropagation()
                          onUnselect(item)
                        }
                      }}
                      onMouseDown={(e) => {
                        e.preventDefault()
                        e.stopPropagation()
                      }}
                      onClick={(e) => {
                        e.stopPropagation()
                        onUnselect(item)
                      }}
                    >
                      <XIcon className="size-3" />
                    </span>
                  </Badge>
                ))}
                {value.length > maxBadges && (
                  <Badge variant="outline">+{value.length - maxBadges}</Badge>
                )}
              </>
            ) : (
              <span className="truncate px-1">{placeholder}</span>
            )}
          </span>
          <span className="flex shrink-0 items-center gap-0.5">
            {selectedItems.length > 0 && (
              <span
                role="button"
                tabIndex={0}
                aria-label="Clear all"
                className="text-muted-foreground hover:text-foreground focus-visible:ring-ring rounded-full p-0.5 outline-none focus-visible:ring-2"
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault()
                    e.stopPropagation()
                    onClear()
                  }
                }}
                onMouseDown={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                }}
                onClick={(e) => {
                  e.stopPropagation()
                  onClear()
                }}
              >
                <XIcon className="size-3.5" />
              </span>
            )}
            {selectedItems.length > 0 && (
              <Separator orientation="vertical" className="mx-1 h-4" />
            )}
            <ChevronsUpDownIcon className="text-muted-foreground mr-1 size-4 shrink-0" />
          </span>
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="p-0"
        style={{
          minWidth: contentWidth,
          maxWidth: "100vw",
        }}
        align="start"
      >
        {children}
      </PopoverContent>
    </Popover>
  )
}

interface AsyncMultiSelectLazyBodyProps<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
> extends Omit<
  AsyncMultiSelectCommandProps<T>,
  "items" | "isFetching" | "error"
> {
  params: TParams
  useDataHook: AsyncMultiSelectFieldProps<T, TParams>["useDataHook"]
}

function AsyncMultiSelectLazyBody<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
>({
  params,
  useDataHook,
  ...commandProps
}: AsyncMultiSelectLazyBodyProps<T, TParams>) {
  const { data, isFetching, error } = useDataHook(params)
  const items = React.useMemo(() => data?.data?.items ?? [], [data])

  return (
    <AsyncMultiSelectCommand
      {...commandProps}
      items={items}
      isFetching={isFetching}
      error={error}
    />
  )
}

interface AsyncMultiSelectEagerProps<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
> {
  value: string[]
  useDataHook: AsyncMultiSelectFieldProps<T, TParams>["useDataHook"]
  selectedItemsDataItems: T[]
  getItemValue: (item: T) => string
  getItemDisplayValue: (item: T) => string
  disabled: boolean
  className?: string
  badgeClassName?: string
  placeholder: string
  maxBadges: number
  state: ReturnType<typeof useAsyncMultiSelectFieldState<TParams>>
  commandProps: Omit<
    AsyncMultiSelectCommandProps<T>,
    "items" | "isFetching" | "error"
  >
  onUnselect: (item: T) => void
  onClear: () => void
}

function AsyncMultiSelectEager<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
>({
  value,
  useDataHook,
  selectedItemsDataItems,
  getItemValue,
  getItemDisplayValue,
  disabled,
  className,
  badgeClassName,
  placeholder,
  maxBadges,
  state,
  commandProps,
  onUnselect,
  onClear,
}: AsyncMultiSelectEagerProps<T, TParams>) {
  const { data, isFetching, error } = useDataHook(state.params)

  const listItems = React.useMemo(() => data?.data?.items ?? [], [data])

  const selectedItems = React.useMemo(
    () =>
      buildSelectedItems(
        listItems,
        selectedItemsDataItems,
        value,
        getItemValue,
      ),
    [listItems, selectedItemsDataItems, value, getItemValue],
  )

  return (
    <AsyncMultiSelectShell
      open={state.open}
      onOpenChange={state.onOpenChange}
      triggerRef={state.triggerRef}
      disabled={disabled}
      className={className}
      value={value}
      selectedItems={selectedItems}
      getItemValue={getItemValue}
      getItemDisplayValue={getItemDisplayValue}
      placeholder={placeholder}
      badgeClassName={badgeClassName}
      maxBadges={maxBadges}
      contentWidth={state.contentWidth}
      onUnselect={onUnselect}
      onClear={onClear}
    >
      <AsyncMultiSelectCommand
        {...commandProps}
        items={listItems}
        isFetching={isFetching}
        error={error}
      />
    </AsyncMultiSelectShell>
  )
}

export function AsyncMultiSelectField<
  T extends SelectFieldItem,
  TParams extends BaseSelectParams,
>({
  value = [],
  onChange,
  placeholder = "Select...",
  debounceDelay = 500,
  searchPlaceholder = "Search...",
  searchParamKey = "search_by_name" as keyof TParams,
  useDataHook,
  selectedItemsData,
  getItemDisplayValue,
  getItemKey,
  getItemValue,
  renderItemLabel,
  additionalParams = {},
  disabled = false,
  className,
  badgeClassName,
  maxSelected,
  maxBadges = 4,
  showSearchIcon = false,
  lazy = false,
  emptyIndicator,
}: AsyncMultiSelectFieldProps<T, TParams>) {
  const state = useAsyncMultiSelectFieldState<TParams>({
    debounceDelay,
    searchParamKey,
    additionalParams,
  })

  const getValue = React.useMemo(
    () => getItemValue ?? defaultGetItemValue,
    [getItemValue],
  )

  const selectedItemsDataItems = React.useMemo(
    () => selectedItemsData?.data?.items ?? [],
    [selectedItemsData],
  )

  const handleToggle = React.useCallback(
    (itemValue: string) => {
      if (value.includes(itemValue)) {
        onChange(value.filter((v) => v !== itemValue))
        return
      }
      if (maxSelected && value.length >= maxSelected) return
      onChange([...value, itemValue])
    },
    [value, onChange, maxSelected],
  )

  const handleUnselect = React.useCallback(
    (item: T) => {
      onChange(value.filter((v) => v !== getValue(item)))
    },
    [value, onChange, getValue],
  )

  const handleClear = React.useCallback(() => {
    if (value.length > 0) onChange([])
  }, [value, onChange])

  const lazySelectedItems = React.useMemo(
    () => buildSelectedItems([], selectedItemsDataItems, value, getValue),
    [selectedItemsDataItems, value, getValue],
  )

  const commandProps: Omit<
    AsyncMultiSelectCommandProps<T>,
    "items" | "isFetching" | "error"
  > = {
    search: state.search,
    setSearch: state.setSearch,
    debouncedSetSearch: state.debouncedSetSearch,
    searchPlaceholder,
    showSearchIcon,
    value,
    maxSelected,
    emptyIndicator,
    getItemKey,
    getItemValue: getValue,
    getItemDisplayValue,
    renderItemLabel,
    onToggle: handleToggle,
  }

  if (lazy) {
    return (
      <AsyncMultiSelectShell
        open={state.open}
        onOpenChange={state.onOpenChange}
        triggerRef={state.triggerRef}
        disabled={disabled}
        className={className}
        value={value}
        selectedItems={lazySelectedItems}
        getItemValue={getValue}
        getItemDisplayValue={getItemDisplayValue}
        placeholder={placeholder}
        badgeClassName={badgeClassName}
        maxBadges={maxBadges}
        contentWidth={state.contentWidth}
        onUnselect={handleUnselect}
        onClear={handleClear}
      >
        {state.open ? (
          <AsyncMultiSelectLazyBody
            {...commandProps}
            params={state.params}
            useDataHook={useDataHook}
          />
        ) : null}
      </AsyncMultiSelectShell>
    )
  }

  return (
    <AsyncMultiSelectEager
      value={value}
      useDataHook={useDataHook}
      selectedItemsDataItems={selectedItemsDataItems}
      getItemValue={getValue}
      getItemDisplayValue={getItemDisplayValue}
      disabled={disabled}
      className={className}
      badgeClassName={badgeClassName}
      placeholder={placeholder}
      maxBadges={maxBadges}
      state={state}
      commandProps={commandProps}
      onUnselect={handleUnselect}
      onClear={handleClear}
    />
  )
}

